using System;using System.IO;using System.Reflection;using MakroSoundSwitch;
class PortableVerify {
 [STAThread]static void Main(){var expected=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"config","scenarios.xml");using(var form=new MainForm()){var flags=BindingFlags.Instance|BindingFlags.NonPublic;var actual=(string)typeof(MainForm).GetField("config",flags).GetValue(form);if(actual!=expected)throw new Exception("Config is not beside executable");Console.WriteLine("PASS: Default config path is beside executable");var data=(Settings)typeof(MainForm).GetField("data",flags).GetValue(form);data.RunAtWindowsStartup=true;data.Scenarios.Add(new Scenario{Name="Portable test",Output="example-output",Input="example-input"});typeof(MainForm).GetMethod("Save",flags).Invoke(form,null);var loaded=SettingsFile.Load(expected);if(!loaded.RunAtWindowsStartup||loaded.Scenarios[loaded.Scenarios.Count-1].Name!="Portable test")throw new Exception("Portable save failed");Console.WriteLine("PASS: Scenarios and startup preference round-trip through portable config");}File.Delete(expected);var backup=expected+".bak";if(File.Exists(backup))File.Delete(backup);Directory.Delete(Path.GetDirectoryName(expected));}
}
